DO $$ BEGIN CREATE TYPE participant_status AS ENUM ('ACTIVE','DEACTIVATED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$; DO $$ BEGIN CREATE TYPE registration_status AS ENUM ('ACTIVE','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$; DO $$ BEGIN CREATE TYPE created_by AS ENUM ('PARTICIPANT','ADMIN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS conferences (id serial PRIMARY KEY,title varchar(200) NOT NULL,slug varchar(100) NOT NULL UNIQUE,description text,location varchar(200),conference_date timestamptz,registration_open boolean NOT NULL DEFAULT true,registration_opens_at timestamptz,registration_closes_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS time_slots (id serial PRIMARY KEY,conference_id integer NOT NULL REFERENCES conferences(id),title varchar(200) NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,sort_order integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS events (id serial PRIMARY KEY,conference_id integer NOT NULL REFERENCES conferences(id),time_slot_id integer NOT NULL REFERENCES time_slots(id),title varchar(250) NOT NULL,description text NOT NULL,speaker_name varchar(150) NOT NULL,speaker_photo_path varchar(500),room varchar(100),capacity integer NOT NULL CHECK(capacity >= 0),booked_count integer NOT NULL DEFAULT 0 CHECK(booked_count >= 0 AND booked_count <= capacity),registration_open boolean NOT NULL DEFAULT true,sort_order integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS participants (id serial PRIMARY KEY,conference_id integer NOT NULL REFERENCES conferences(id),ticket_number varchar(50) NOT NULL UNIQUE,first_name varchar(100) NOT NULL,last_name varchar(100) NOT NULL,city varchar(150) NOT NULL,email varchar(254) NOT NULL,normalized_email varchar(254) NOT NULL,ticket_token_hash varchar(64) NOT NULL UNIQUE,status participant_status NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conference_id,normalized_email));
CREATE TABLE IF NOT EXISTS registrations (id serial PRIMARY KEY,participant_id integer NOT NULL REFERENCES participants(id),event_id integer NOT NULL REFERENCES events(id),time_slot_id integer NOT NULL REFERENCES time_slots(id),status registration_status NOT NULL DEFAULT 'ACTIVE',created_by created_by NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz); CREATE UNIQUE INDEX IF NOT EXISTS registrations_participant_slot_active_unique ON registrations(participant_id,time_slot_id) WHERE status='ACTIVE'; CREATE INDEX IF NOT EXISTS registrations_event_idx ON registrations(event_id);
CREATE TABLE IF NOT EXISTS admins (id serial PRIMARY KEY,login varchar(100) NOT NULL UNIQUE,password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,last_login_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (id serial PRIMARY KEY,admin_id integer NOT NULL REFERENCES admins(id),session_token_hash varchar(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,last_used_at timestamptz NOT NULL DEFAULT now(),ip_address varchar(64),user_agent varchar(500),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (id serial PRIMARY KEY,key varchar(100) NOT NULL,operation varchar(50) NOT NULL,response_data jsonb,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,UNIQUE(key,operation));
CREATE TABLE IF NOT EXISTS audit_logs (id serial PRIMARY KEY,admin_id integer REFERENCES admins(id),action varchar(100) NOT NULL,entity_type varchar(50) NOT NULL,entity_id varchar(100) NOT NULL,old_data jsonb,new_data jsonb,ip_address varchar(64),user_agent varchar(500),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE participants ADD COLUMN IF NOT EXISTS role varchar(30) NOT NULL DEFAULT 'GUEST';
ALTER TABLE events ADD COLUMN IF NOT EXISTS allowed_roles varchar(30)[] NOT NULL DEFAULT ARRAY['COORDINATOR','ADMINISTRATOR','EMPLOYEE','GUEST','OTHER'];
ALTER TABLE participants ADD COLUMN IF NOT EXISTS phone varchar(30) NOT NULL DEFAULT '';
ALTER TABLE participants ADD COLUMN IF NOT EXISTS normalized_phone varchar(20) NOT NULL DEFAULT '';
CREATE UNIQUE INDEX IF NOT EXISTS participants_conference_phone_unique ON participants(conference_id,normalized_phone) WHERE normalized_phone <> '';
